function parseVocab(text){
  text=(text||'').replace(/\r/g,'');
  var lines=text.split('\n'), out=[];
  for(var i=0;i<lines.length;i++){ var ln=lines[i].trim(); if(!ln) continue;
    var mm=ln.split(/\s*(?:\|\||[|｜])\s*/); out.push({term:mm[0].trim(), def:(mm[1]||'').trim()}); }
  return out;
}
function shuffle(arr, rng){ var a=arr.slice(); for(var i=a.length-1;i>0;i--){var j=Math.floor(rng()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;} return a; }
var EXPORTS={parseVocab:parseVocab, shuffle:shuffle};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.VocabForgePure = EXPORTS; }
